"""Ingest UTF-8 Python sources from a folder of repositories."""

from __future__ import annotations

from collections.abc import Iterator
from pathlib import Path
from typing import Any

from toklab.core.hashing import sha256_text
from toklab.core.types import SourceFile

MAX_FILE_BYTES = 1_048_576  # 1 MiB
GENERATED_MARKERS = (
    "@generated",
    "auto-generated",
    "automatically generated",
    "do not edit",
    "generated by",
)

_DEFAULT_INGEST_YAML = (
    Path(__file__).resolve().parents[3] / "configs" / "ingest.yaml"
)


def _default_ingest_yaml() -> Path:
    candidates = [
        Path.cwd() / "configs" / "ingest.yaml",
        _DEFAULT_INGEST_YAML,
    ]
    for path in candidates:
        if path.is_file():
            return path
    return candidates[0]


def load_ingest_config(path: Path | str | None = None) -> dict[str, Any]:
    """Load ``configs/ingest.yaml`` (skip dir/file names)."""
    import yaml

    cfg_path = Path(path) if path is not None else _default_ingest_yaml()
    if not cfg_path.is_file():
        raise FileNotFoundError(f"ingest config not found: {cfg_path}")
    data = yaml.safe_load(cfg_path.read_text(encoding="utf-8"))
    if not isinstance(data, dict):
        raise ValueError(f"{cfg_path} must be a mapping")
    dirs = data.get("skip_dir_names")
    files = data.get("skip_file_names")
    if not isinstance(dirs, list) or not dirs:
        raise ValueError(f"{cfg_path}: skip_dir_names must be a non-empty list")
    if not isinstance(files, list):
        raise ValueError(f"{cfg_path}: skip_file_names must be a list")
    return {
        "skip_dir_names": frozenset(str(x) for x in dirs),
        "skip_file_names": frozenset(str(x) for x in files),
    }


def _is_skipped_path(
    rel: Path,
    *,
    skip_dir_names: frozenset[str],
    skip_file_names: frozenset[str],
) -> bool:
    if rel.name in skip_file_names:
        return True
    return any(part in skip_dir_names for part in rel.parts)


def _looks_generated(path: Path, text: str) -> bool:
    if "generated" in path.name.lower():
        return True
    head = "\n".join(text.splitlines()[:40]).lower()
    return any(marker in head for marker in GENERATED_MARKERS)


def _read_utf8_text(path: Path) -> str | None:
    """Return decoded text, or None if binary / not valid UTF-8."""
    raw = path.read_bytes()
    if b"\x00" in raw:
        return None
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError:
        return None


def ingest_repos(
    repos_dir: Path | str,
    *,
    config_path: Path | str | None = None,
) -> Iterator[SourceFile]:
    """Yield SourceFile records for eligible ``.py`` files under ``repos_dir``.

    Each immediate child directory of ``repos_dir`` is treated as one
    repository. Originals are never modified. Files are skipped when they
    exceed 1 MiB, are not valid UTF-8, match skip lists in
    ``configs/ingest.yaml``, or carry generated-file markers.
    """
    root = Path(repos_dir)
    if not root.is_dir():
        raise FileNotFoundError(f"repos directory not found: {root}")

    cfg = load_ingest_config(config_path)
    skip_dirs: frozenset[str] = cfg["skip_dir_names"]
    skip_files: frozenset[str] = cfg["skip_file_names"]

    repo_dirs = sorted(
        p for p in root.iterdir() if p.is_dir() and not p.name.startswith(".")
    )
    for repo_dir in repo_dirs:
        repo = repo_dir.name
        for path in sorted(repo_dir.rglob("*.py")):
            if not path.is_file():
                continue
            rel = path.relative_to(repo_dir)
            if _is_skipped_path(
                rel, skip_dir_names=skip_dirs, skip_file_names=skip_files
            ):
                continue
            n_bytes = path.stat().st_size
            if n_bytes > MAX_FILE_BYTES:
                continue
            text = _read_utf8_text(path)
            if text is None:
                continue
            if _looks_generated(path, text):
                continue
            digest = sha256_text(text)
            file_id = sha256_text(f"{repo}:{rel.as_posix()}")
            yield SourceFile(
                file_id=file_id,
                repo=repo,
                path=rel.as_posix(),
                sha256=digest,
                language="python",
                n_bytes=n_bytes,
                split="",
            )
